// Copies the stylesheets and the JSON manifests next to the compiled JavaScript in dist/.
// The manifest i18n-keys.json is generated by `pnpm i18n:manifest` and committed; it is copied, not regenerated, so
// `check-package` can tell a stale manifest from a fresh one.
import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const dist = path.join(root, 'dist');
const copies = [
  ['src/theme.css', 'theme.css'],
  ['src/components.css', 'components.css'],
  ['tokens.json', 'tokens.json'],
  ['i18n-keys.json', 'i18n-keys.json'],
];

for (const [from, to] of copies) {
  const source = path.join(root, from);
  if (!fs.existsSync(source)) {
    console.error(`copy-assets: ${from} is missing${from === 'i18n-keys.json' ? ' (run `pnpm i18n:manifest`)' : ''}`);
    process.exit(1);
  }
  fs.mkdirSync(path.dirname(path.join(dist, to)), { recursive: true });
  fs.copyFileSync(source, path.join(dist, to));
  console.log(`copied  ${from} → dist/${to}`);
}
